import java.util.*;

class Solution {
  public int minOperations(List<Integer> nums, int target) {
    long sum = 0;
    int[] counts = new int[31];
    for (int value : nums) {
      sum += value;
      counts[Integer.numberOfTrailingZeros(value)]++;
    }
    if (sum < target) return -1;
    int operations = 0;
    for (int bit = 0; bit < 31; bit++) {
      if (((target >>> bit) & 1) != 0) {
        if (counts[bit] > 0) {
          counts[bit]--;
        } else {
          int next = bit + 1;
          while (next < 31 && counts[next] == 0) next++;
          while (next > bit) {
            counts[next]--;
            counts[next - 1] += 2;
            operations++;
            next--;
          }
          counts[bit]--;
        }
      }
      if (bit + 1 < 31) counts[bit + 1] += counts[bit] / 2;
    }
    return operations;
  }
}
